type Currency = "HKD"|"CNY"|"TWD"|"JPY"|"KRW"|"THB"|"IDR"|"SGD"|"MYR"|"USD"|"EUR"|"GBP"|"CAD"|"AUD"|"NZD"|"PHP"|"VND";
