function normalizeData(input:Partial<AppData>&{expenses?:Array<Partial<Expense>>}):AppData{
  const legacySettings=input.settings as AppData["settings"]&{tripBudgets?:Record<string,number>;tripRates?:TripRates;tripLastCurrencies?:TripLastCurrencies};
  const tripNames=[...new Set((input.expenses||[]).filter(raw=>raw.expenseType==="travel"&&raw.tripName?.trim()).map(raw=>raw.tripName!.trim()))];
  const tripSplits:TripSplits={};
  tripNames.forEach(name=>{const fallback=defaultTripSplit(name),raw=input.tripSplits?.[name];const members=(raw?.members||fallback.members).filter(member=>member?.memberId&&member?.name?.trim()).map(member=>({...member,name:member.name.trim(),active:member.active!==false}));const safeMembers=members.length?members:fallback.members;tripSplits[name]={enabled:raw?.enabled===true,members:safeMembers,lastPayerId:safeMembers.some(member=>member.memberId===raw?.lastPayerId)?raw!.lastPayerId:safeMembers[0].memberId}});
  const expenses=(input.expenses||[]).map(raw=>{const expenseType=raw.expenseType==="travel"&&raw.tripName?.trim()?"travel":"daily",tripName=expenseType==="travel"?raw.tripName!.trim():undefined;if(!tripName)return{...raw,expenseType,tripName:undefined,payerMemberId:undefined,splitMemberIds:undefined,splitShares:undefined};const config=tripSplits[tripName]||defaultTripSplit(tripName),self=config.members[0].memberId,payer=config.members.some(member=>member.memberId===raw.payerMemberId)?raw.payerMemberId!:self,selected=(raw.splitMemberIds||[]).filter(id=>config.members.some(member=>member.memberId===id)),splitMemberIds=selected.length?selected:[self],validShares=(raw.splitShares||[]).filter(share=>splitMemberIds.includes(share.memberId)&&Number.isFinite(share.amount));return{...raw,expenseType,tripName,payerMemberId:payer,splitMemberIds,splitShares:validShares.length===splitMemberIds.length?validShares:splitAmount(Number(raw.amount)||0,splitMemberIds,currencyDigits(raw.currency as Currency))}}) as Expense[];
  const tripRates:TripRates={...(legacySettings?.tripRates||{}),...(input.tripRates||{})};
  expenses.filter(e=>e.expenseType==="travel"&&e.tripName).sort((a,b)=>a.date.localeCompare(b.date)||a.createdAt-b.createdAt).forEach(e=>{const name=e.tripName!;tripRates[name]||={};if(tripRates[name][e.currency]==null)tripRates[name][e.currency]=e.rate});
  const tripLastCurrencies:TripLastCurrencies={...(legacySettings?.tripLastCurrencies||{}),...(input.tripLastCurrencies||{})};
  expenses.filter(e=>e.expenseType==="travel"&&e.tripName).sort((a,b)=>a.createdAt-b.createdAt).forEach(e=>{if(!input.tripLastCurrencies?.[e.tripName!])tripLastCurrencies[e.tripName!]=e.currency});
  const categories=(input.categories||DEFAULT_CATEGORIES).map(category=>({...category,subcategories:categorySubcategories(category)}));
  const updatedAt=Number.isFinite(input.updatedAt)?Number(input.updatedAt):expenses.reduce((latest,expense)=>Math.max(latest,Number(expense.createdAt)||0),0);
  return{version:5,updatedAt,expenses,categories,rates:{...DEFAULT_RATES,...input.rates},monthlyBudgets:{...(input.monthlyBudgets||{})},tripBudgets:{...(legacySettings?.tripBudgets||{}),...(input.tripBudgets||{})},tripRates,tripLastCurrencies,tripSplits,settings:{baseCurrency:"HKD",rateUpdated:input.settings?.rateUpdated||"預設參考匯率",lastMode:input.settings?.lastMode==="travel"?"travel":"daily",lastTrip:input.settings?.lastTrip||"",chartMode:input.settings?.chartMode==="donut"?"donut":"bar"}};
}
function openDatabase():Promise<IDBDatabase>{return new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains(DB_STORE))r.result.createObjectStore(DB_STORE)};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function readDatabase():Promise<AppData|null>{const db=await openDatabase();return new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,"readonly"),r=tx.objectStore(DB_STORE).get(DB_KEY);r.onsuccess=()=>resolve(r.result?normalizeData(r.result):null);r.onerror=()=>reject(r.error);tx.oncomplete=()=>db.close()})}
async function writeDatabase(data:AppData):Promise<void>{const db=await openDatabase();return new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,"readwrite");tx.objectStore(DB_STORE).put(data,DB_KEY);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
function readLegacyData():AppData|null{try{const ex=localStorage.getItem("antony-expenses"),cats=localStorage.getItem("antony-categories"),rates=localStorage.getItem("antony-rates");if(!ex&&!cats&&!rates)return null;return normalizeData({expenses:ex?JSON.parse(ex):[],categories:cats?JSON.parse(cats):DEFAULT_CATEGORIES,rates:rates?JSON.parse(rates):DEFAULT_RATES,tripBudgets:{...JSON.parse(localStorage.getItem("my-expenses-trip-budgets")||"{}"),...JSON.parse(localStorage.getItem("antony-trip-budgets")||"{}")},tripRates:{...JSON.parse(localStorage.getItem("my-expenses-trip-rates")||"{}"),...JSON.parse(localStorage.getItem("antony-trip-rates")||"{}")},tripLastCurrencies:JSON.parse(localStorage.getItem("antony-trip-last-currencies")||"{}"),tripSplits:JSON.parse(localStorage.getItem("antony-trip-splits")||"{}"),settings:{baseCurrency:"HKD",rateUpdated:localStorage.getItem("antony-rate-updated")||"預設參考匯率",lastMode:localStorage.getItem("antony-last-mode")==="travel"?"travel":"daily",lastTrip:localStorage.getItem("antony-last-trip")||""}})}catch{return null}}
function readLocalData():AppData|null{try{const snapshot=localStorage.getItem(LOCAL_SNAPSHOT_KEY);if(snapshot)return normalizeData(JSON.parse(snapshot))}catch{/* Fall through to legacy keys. */}return readLegacyData()}
function mirror(data:AppData):boolean{try{localStorage.setItem(LOCAL_SNAPSHOT_KEY,JSON.stringify(data));localStorage.setItem("antony-expenses",JSON.stringify(data.expenses));localStorage.setItem("antony-categories",JSON.stringify(data.categories));localStorage.setItem("antony-rates",JSON.stringify(data.rates));localStorage.setItem("antony-trip-budgets",JSON.stringify(data.tripBudgets));localStorage.setItem("antony-trip-rates",JSON.stringify(data.tripRates));localStorage.setItem("antony-trip-last-currencies",JSON.stringify(data.tripLastCurrencies));localStorage.setItem("antony-trip-splits",JSON.stringify(data.tripSplits));localStorage.setItem("antony-rate-updated",data.settings.rateUpdated);localStorage.setItem("antony-last-mode",data.settings.lastMode||"daily");localStorage.setItem("antony-last-trip",data.settings.lastTrip||"");return true}catch{return false}}
function download(content:string,name:string,type:string){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csvCell(value:string|number|undefined){return `"${String(value??"").replaceAll('"','""')}"`}
async function fetchRate(currency:Currency,fallback:number){if(currency==="HKD")return 1;try{const response=await fetch("https://open.er-api.com/v6/latest/HKD"),data=await response.json(),value=Number(data?.rates?.[currency]);if(!response.ok||!value)throw new Error();return 1/value}catch{return fallback}}

