function Calculator({initial,onClose,onUse}:{initial:string;onClose:()=>void;onUse:(value:string)=>void}){
  const[expression,setExpression]=useState(initial||""),[result,setResult]=useState(initial||"0"),[error,setError]=useState("");
  function evaluate(){try{const value=calculateExpression(expression);setResult(Number.isInteger(value)?String(value):String(Number(value.toFixed(8))));setError("")}catch(reason){setError(reason instanceof Error&&reason.message==="DIV_ZERO"?"不能除以零":reason instanceof Error&&reason.message==="TOO_LARGE"?"數字太大":"算式無效")}}
  function press(key:string){setError("");if(key==="C"){setExpression("");setResult("0");return}if(key==="⌫"){setExpression(value=>value.slice(0,-1));return}if(key==="="){evaluate();return}setExpression(value=>value.length>=120?value:`${value}${key}`)}
  return <div className="modal-backdrop calculator-layer"><div className="mini-sheet calculator"><div className="sheet-head"><button type="button" onClick={onClose}>關閉</button><h2>簡易計數機</h2><span/></div><div className="calculator-display"><small>{expression||"輸入算式"}</small><strong>{error||result}</strong></div><div className="calculator-grid">{["C","⌫","÷","×","7","8","9","-","4","5","6","+","1","2","3","=","0","."].map(key=><button type="button" key={key} className={key==="="?"equals":["÷","×","-","+"].includes(key)?"operator":["C","⌫"].includes(key)?"utility":"number-key"} onClick={()=>press(key)}>{key}</button>)}</div><button className="calculator-use" type="button" disabled={!!error||!expression} onClick={()=>{try{const value=calculateExpression(expression);if(value<0){setError("金額不可為負數");return}onUse(Number.isInteger(value)?String(value):String(Number(value.toFixed(8))))}catch{evaluate()}}}>使用此金額</button></div></div>
}
function MemberManager({config,expenses,notify,onClose,onChange}:{config:TripSplit;expenses:Expense[];notify:(message:string)=>void;onClose:()=>void;onChange:(config:TripSplit)=>void}){
  const[newName,setNewName]=useState("");
  const usedIds=new Set(expenses.flatMap(expense=>[expense.payerMemberId,...(expense.splitMemberIds||[])]).filter(Boolean));
  function add(){const name=newName.trim();if(!name)return;if(config.members.some(member=>member.name===name)){notify("同一旅程已有相同名稱");return}onChange({...config,members:[...config.members,{memberId:makeId(),name,active:true}]});setNewName("")}
  function rename(memberId:string,name:string){const trimmed=name.trim();if(!trimmed||config.members.some(member=>member.memberId!==memberId&&member.name===trimmed)){notify(!trimmed?"成員名稱不可留空":"同一旅程已有相同名稱");return}onChange({...config,members:config.members.map(member=>member.memberId===memberId?{...member,name:trimmed}:member)})}
  function toggle(memberId:string){const member=config.members.find(item=>item.memberId===memberId);if(!member)return;if(member.memberId===config.members[0].memberId&&member.active){notify("我自己需要保留啟用");return}onChange({...config,members:config.members.map(item=>item.memberId===memberId?{...item,active:!item.active}:item)})}
  return <div className="modal-backdrop"><div className="mini-sheet member-manager"><div className="sheet-head"><button type="button" onClick={onClose}>完成</button><h2>同行成員</h2><span/></div><p>每個旅程獨立保存；停用成員仍會保留舊記錄。</p><div className="member-list">{config.members.map(member=><div key={member.memberId}><input aria-label={`${member.name}名稱`} defaultValue={member.name} onBlur={event=>rename(member.memberId,event.target.value)}/><button type="button" className={member.active?"active":""} onClick={()=>toggle(member.memberId)}>{member.active?"啟用中":usedIds.has(member.memberId)?"已停用 · 保留舊帳":"已停用"}</button></div>)}</div><div className="member-add"><input value={newName} onChange={event=>setNewName(event.target.value)} placeholder="同行成員姓名"/><button type="button" onClick={add}>＋ 新增同行成員</button></div></div></div>
}
function CategoryEditor({value,onClose,onSave,onDelete}:{value:Category|null;onClose:()=>void;onSave:(n:string,s:string[])=>void;onDelete?:()=>void}){const[name,setName]=useState(value?.name||""),[subs,setSubs]=useState<string[]>(value?.subcategories||[]),[newSub,setNewSub]=useState("");function pendingSubs(){return cleanSubcategories([...subs,...newSub.split(/[，,、\n]/)])}function add(){const next=pendingSubs();if(next.length!==subs.length)setSubs(next);setNewSub("")}return <div className="modal-backdrop"><form className="mini-sheet" onSubmit={e=>{e.preventDefault();if(name.trim())onSave(name.trim(),pendingSubs())}}><div className="sheet-head"><button type="button" onClick={onClose}>取消</button><h2>{value?"編輯分類":"新增分類"}</h2><button disabled={!name.trim()}>儲存</button></div><label>分類名稱<input autoFocus value={name} onChange={e=>setName(e.target.value)} placeholder="輸入分類名稱"/></label><div className="subcategory-editor"><strong>細分類</strong><div className="subcategory-add"><input value={newSub} onChange={e=>setNewSub(e.target.value)} placeholder="例如：巴士"/><button type="button" onClick={add}>加入</button></div><small>加入後仍要按右上角「儲存」；直接按「儲存」亦會保留輸入框中的細分類。</small><div className="subcategory-list">{subs.map((s,i)=><span key={`${s}-${i}`}>{s}<button type="button" onClick={()=>setSubs(v=>v.filter((_,x)=>x!==i))}>×</button></span>)}</div></div>{onDelete&&<button type="button" className="delete-button" onClick={onDelete}>刪除分類</button>}</form></div>}
function ExpenseRow({e,category,onClick}:{e:Expense;category?:Category;onClick:()=>void}){return <button className="expense-row" onClick={onClick}><span className="category-icon">{category?.name.slice(0,1)||"其"}</span><span className="expense-main"><strong>{category?.name||"其他"}{e.subcategory?` · ${e.subcategory}`:""}</strong><small>{shortDate(e.date)}{e.tripName?` · ${e.tripName}`:""}{e.note?` · ${e.note}`:""}</small></span><span className="expense-money"><strong>{money(e.hkdAmount)}</strong>{e.currency!=="HKD"&&<small>{originalMoney(e.amount,e.currency)}</small>}</span></button>}
